<script setup>
import { $api } from '@/utils/api'

const items = ref([]); const meta = ref({ members: [], sport_codes: [], periods: [] }); const dialog = ref(false); const detail = ref(null); const status = ref(null)
const form = reactive({ member_id: null, sport_code_id: null, membership_category_id: null, membership_period_id: null, application_type: 'new_membership', applicant_notes: '', joining_fee: 0, discount: 0, override_reason: '', guardian_name: '', guardian_relationship: '', guardian_email: '', guardian_mobile: '', guardian_consent: false, independent_access_permitted: false })
const selectedCode = computed(() => meta.value.sport_codes.find(c => c.id === form.sport_code_id))
const selectedMember = computed(() => meta.value.members.find(m => m.id === form.member_id))
const junior = computed(() => selectedMember.value?.date_of_birth && new Date().getFullYear() - Number(selectedMember.value.date_of_birth.slice(0,4)) < 18)
const money = cents => new Intl.NumberFormat('en-ZA',{ style:'currency',currency:'ZAR' }).format((cents || 0)/100)
async function load() { const [list, info] = await Promise.all([$api('/membership-applications',{ query: status.value ? { status: status.value } : {} }), $api('/membership-applications/meta')]); items.value=list.data; meta.value=info }
async function create() { await $api('/membership-applications',{method:'POST',body:form}); dialog.value=false; await load() }
async function view(item) { detail.value=await $api(`/membership-applications/${item.id}`) }
async function action(name, reason=null) { await $api(`/membership-applications/${detail.value.id}/action`,{method:'POST',body:{action:name,reason}}); detail.value=null; await load() }
watch(status,load); onMounted(load)
</script>
<template><div>
  <div class="d-flex justify-space-between align-center mb-6"><div><h3 class="text-h3">Membership applications</h3><p class="text-medium-emphasis mb-0">Applications are reviewed before a sport membership is activated.</p></div><VBtn prepend-icon="tabler-plus" @click="dialog=true">New application</VBtn></div>
  <VCard><VCardText><VSelect v-model="status" label="Status" :items="['draft','submitted','under_review','information_required','approved','rejected','withdrawn','cancelled']" clearable hide-details style="max-width:280px" /></VCardText><VTable><thead><tr><th>Member</th><th>Sport / category</th><th>Type</th><th>Period</th><th>Status</th><th>Total</th><th /></tr></thead><tbody><tr v-for="a in items" :key="a.id"><td>{{ a.member.display_name }}<div class="text-caption">{{ a.member.member_number }}</div></td><td>{{ a.sport_code.name }} · {{ a.category.name }}</td><td>{{ a.application_type.replaceAll('_',' ') }}</td><td>{{ a.period.name }}</td><td><VChip size="small" variant="tonal">{{ a.status.replaceAll('_',' ') }}</VChip></td><td>{{ a.total_payable_cents === null ? 'Draft pricing' : money(a.total_payable_cents) }}</td><td><VBtn icon="tabler-chevron-right" variant="text" @click="view(a)" /></td></tr></tbody></VTable></VCard>
  <VDialog v-model="dialog" max-width="800"><VCard><VCardTitle class="pa-6">New membership application</VCardTitle><VCardText><VRow><VCol cols="12" md="6"><VSelect v-model="form.member_id" label="Member" :items="meta.members" :item-title="m => `${m.first_name} ${m.last_name} (${m.member_number})`" item-value="id" /></VCol><VCol cols="12" md="6"><VSelect v-model="form.application_type" label="Application type" :items="['new_membership','additional_sport','renewal','category_change','reinstatement']" /></VCol><VCol cols="12" md="4"><VSelect v-model="form.sport_code_id" label="Sport code" :items="meta.sport_codes" item-title="name" item-value="id" /></VCol><VCol cols="12" md="4"><VSelect v-model="form.membership_category_id" label="Category" :items="selectedCode?.categories || []" item-title="name" item-value="id" /></VCol><VCol cols="12" md="4"><VSelect v-model="form.membership_period_id" label="Period" :items="meta.periods" item-title="name" item-value="id" /></VCol><VCol cols="12"><VTextarea v-model="form.applicant_notes" label="Application notes" /></VCol><template v-if="junior"><VCol cols="12"><VAlert type="info" variant="tonal">Junior application: guardian and consent are required.</VAlert></VCol><VCol cols="6"><VTextField v-model="form.guardian_name" label="Guardian name" /></VCol><VCol cols="6"><VTextField v-model="form.guardian_relationship" label="Relationship" /></VCol><VCol cols="6"><VTextField v-model="form.guardian_email" label="Guardian email" /></VCol><VCol cols="6"><VTextField v-model="form.guardian_mobile" label="Guardian mobile" /></VCol><VCol cols="12"><VCheckbox v-model="form.guardian_consent" label="Guardian consent recorded" /></VCol></template></VRow></VCardText><VCardActions class="pa-6"><VSpacer/><VBtn variant="tonal" @click="dialog=false">Cancel</VBtn><VBtn @click="create">Create draft</VBtn></VCardActions></VCard></VDialog>
  <VNavigationDrawer v-model="detail" location="right" temporary width="520"><div v-if="detail" class="pa-6"><div class="d-flex justify-space-between"><h4 class="text-h4">{{ detail.member.display_name }}</h4><VBtn icon="tabler-x" variant="text" @click="detail=null"/></div><p>{{ detail.sport_code.name }} · {{ detail.category.name }} · {{ detail.period.name }}</p><VChip variant="tonal">{{ detail.status }}</VChip><VDivider class="my-5"/><h5 class="text-h5 mb-3">Fee snapshot</h5><p>Sport fee: {{ money(detail.sport_code_fee_cents) }}<br>HSC levy: {{ money(detail.hsc_levy_cents) }}<br>Discount: {{ money(detail.discount_cents) }}</p><h4>Total: {{ money(detail.total_payable_cents) }}</h4><VDivider class="my-5"/><div class="d-flex flex-wrap gap-2"><VBtn v-if="['draft','information_required'].includes(detail.status)" @click="action('submit')">Submit</VBtn><VBtn v-if="detail.status==='submitted'" @click="action('begin_review')">Begin review</VBtn><VBtn v-if="detail.status==='under_review'" color="success" @click="action('approve')">Approve</VBtn><VBtn v-if="detail.status==='under_review'" color="error" variant="tonal" @click="action('reject',prompt('Rejection reason'))">Reject</VBtn><VBtn v-if="detail.status==='under_review'" variant="tonal" @click="action('request_information')">Request information</VBtn></div></div></VNavigationDrawer>
</div></template>
